src=[(1,1),(2,5),(4,2),(5,5),(7,1)]
tgt=[(0,0),(0,2),(2,0),(0,3),(2,2)]
# coefficient mappings exact under modulo and permutations
solutions=[]
for perm in itertools.permutations(tgt):
 for a,b,q in itertools.product(range(3), repeat=3):
  if all((a*r+b*c+q)%3==t[0] for (r,c),t in zip(src,perm)):
   for d,e,p0 in itertools.product(range(6),repeat=3):
    if all((d*r+e*c+p0)%6==t[1] for (r,c),t in zip(src,perm)):
     solutions.append((perm,(a,b,q,d,e,p0)))
     break
   if solutions: break
  if solutions: break
 if solutions:break
print(solutions[:1])

